head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS20100.xml';
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.pBndApplId = '';
scwin.pBndListProcsTpCd = '';
scwin.pMktactCd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_Search
 * 설명       : 리스트를 조회 한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_ANUL_FEE_REFND_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.selectAnulfeeRefndProcs';
    var param = '';
    param += '&{P}V_ISUR_CD=' + $c.stf.getObjectValue(txb_IsurNm);
    param += '&{P}V_ISU_CD_NM=' + $c.stf.getObjectValue(txb_IsuNm);
    param += '&{P}V_TERM_TYP=' + $c.stf.getObjectValue(cmb_TermType);
    param += '&{P}V_START_DD=' + $c.stf.getObjectValue(edt_StartDd);
    param += '&{P}V_END_DD=' + $c.stf.getObjectValue(edt_EndDd);
    param += '&{P}V_BND_TP_CD=' + $c.stf.getObjectValue(cmb_BndTpCd);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터 정의 (채권유형코드)
 ***********************************************/
scwin.fn_SetComboCode = function() {
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_BndTpCd, '01422');
    if (dts_BndTpCd.getCellData(1, "VALUE") == '') {
        dts_BndTpCd.setCellData(1, "TEXT", '전체');
        cmb_BndTpCd.setSelectedIndex(0);
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, scwin.arrPar[0].ISUR_CD);
};

/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(txb_IsurNm) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(txb_IsurNm);
};



/********************************************** 
 * 함수명   : fn_GetParIsuCd
 * 설명       : 상장채권종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuCd = function(arrPar) {
    scwin.arrPar[0] = {
        LIST_TYPE_CD: '2',
        ISU_NM: $c.stf.getObjectValue(txb_IsuNm),
        ISUR_NM: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsuCd
 * 설명       : 상장채권종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsuCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsuNm, scwin.arrPar[0].STD_CD);
};

/********************************************** 
 * 함수명   : fn_ShowIsu
 * 설명       : 상장채권종목 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsu = function(IsuNm) {
    scwin.fn_GetPar = fn_GetParIsuCd;
    scwin.fn_SetPar = fn_SetParIsuCd;
    $c.bns.fn_PopListBndIsuSearch(txb_IsuNm);
};


/********************************************** 
 * 함수명   : fn_AnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_AnfeeRefnd = function(arrPar) {
    scwin.arrPar[0] = {
        BND_APPL_ID: scwin.pBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.pBndListProcsTpCd,
        MKTACT_TP_CD: scwin.pMktactCd,
        SCREN_ID: scwin.vScrenID
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetAnfeeRefnd
 * 설명       : 연부과금 환급수수료 등록 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetAnfeeRefnd = function(arrPar) {
    if ("Y" == scwin.arrPar[0].REG_YN) {
        dts_List.Reset();
    }
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);

    //채권유형코드
    scwin.fn_SetComboCode();

    //조회 시작일 -7일, 종료일 현재일자로 설정
    $c.stf.setObjectValue(edt_StartDd, $c.ut.cGetMinusDate2(scwin.vCurDate, 7));
    $c.stf.setObjectValue(edt_EndDd, scwin.vCurDate);

    //발행기관 검색 필드 포커스
    txb_IsurNm.focus();
    //조회
    scwin.fn_Search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.img_com_srch_onclick = function() {
    scwin.fn_ShowIsur(txb_IsurNm);
};
scwin.txb_IsurNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
        if (window.event.keyCode == 13) scwin.fn_Search();
    }
};
scwin.img_IsuNm_onclick = function() {
    scwin.fn_ShowIsu(txb_IsuNm);
};
scwin.txb_IsuNm_onkeypress = function() {
    if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
        if (window.event.keyCode == 13) scwin.fn_Search();
    }
};
scwin.img_StartDd_onclick = function() {
    popUpCalendar2(edt_StartDd);
};
scwin.img_EndDd_onclick = function() {
    popUpCalendar2(edt_EndDd);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.compareFromToDate2(edt_StartDd, edt_EndDd)) {
        scwin.fn_Search();
    }
};
scwin.btn_ToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var title = '연부과금 환급처리내역';
    var fileNm = scwin.vCurDate + '_' + title;
    $c.data.downloadGridViewExcel(grd_List, title, "", "8");
};
scwin.grd_List_OnDblClick = function(row, colid) {
    if (dts_List.getTotalRow() == 0) return;
    if (row > 0) {
        scwin.pBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        scwin.pBndListProcsTpCd = dts_List.getCellData(row, "BND_LIST_PROCS_TP_CD");
        scwin.pMktactCd = dts_List.getCellData(row, "BND_MKTACT_TP_CD");
        scwin.fn_GetPar = fn_AnfeeRefnd;
        scwin.fn_SetPar = fn_SetAnfeeRefnd;
        $c.bns.fn_PopAnfeeRefnd(grd_List);
    }
};
